// health.js - Handles PKU Health Center Opening Hours & Clinic Services
function initPkuHoursPill() {
    const pill = document.getElementById("pkuHoursPill");
    const icon = document.getElementById("pkuPillIcon");
    const text = document.getElementById("pkuPillText");
    const badge = document.getElementById("pkuPillBadge");
    if (!pill || !text) return;

    // Semester Breaks (Mon - Fri: 8:00 AM - 5:00 PM, Weekends Closed)
    const semesterBreaks = [
        { start: "2026-08-31", end: "2026-09-27" },
        { start: "2026-11-07", end: "2026-11-15" },
        { start: "2027-02-01", end: "2027-03-21" },
        { start: "2027-05-08", end: "2027-05-16" },
        { start: "2027-07-26", end: "2027-09-26" }
    ];

    // Public Holidays (Closed)
    const holidays = {
        "2026-08-31": { en: "National Day", ms: "Hari Kebangsaan" },
        "2026-09-16": { en: "Malaysia Day", ms: "Hari Malaysia" },
        "2026-09-24": { en: "Maulidur Rasul", ms: "Maulidur Rasul" },
        "2026-11-08": { en: "Deepavali", ms: "Hari Deepavali" },
        "2026-12-25": { en: "Christmas Day", ms: "Hari Krismas" },
        "2027-01-01": { en: "New Year's Day", ms: "Tahun Baru 2027" },
        "2027-02-06": { en: "Chinese New Year", ms: "Tahun Baru Cina" },
        "2027-02-07": { en: "Chinese New Year", ms: "Tahun Baru Cina" },
        "2027-03-09": { en: "Hari Raya Aidilfitri", ms: "Hari Raya Aidilfitri" },
        "2027-03-10": { en: "Hari Raya Aidilfitri", ms: "Hari Raya Aidilfitri" },
        "2027-05-01": { en: "Labour Day", ms: "Hari Pekerja" },
        "2027-05-20": { en: "Wesak Day", ms: "Hari Wesak" }
    };

    function updatePkuPill() {
        const now = new Date();
        const isMs = (typeof currentLang !== 'undefined' && currentLang === 'ms') || document.documentElement.lang === 'ms';

        const year = now.getFullYear();
        const month = String(now.getMonth() + 1).padStart(2, '0');
        const dayOfMonth = String(now.getDate()).padStart(2, '0');
        const dateKey = `${year}-${month}-${dayOfMonth}`;

        const day = now.getDay(); // 0 = Sunday, 1 = Monday, ... 6 = Saturday
        const timeMinutes = now.getHours() * 60 + now.getMinutes();

        const isBreak = semesterBreaks.some(sb => dateKey >= sb.start && dateKey <= sb.end);
        const holiday = holidays[dateKey];

        function applyPill(glowClass, iconChar, textStr, badgeText, badgeBg, badgeColor) {
            pill.classList.remove("glow-pku-open", "glow-pku-closed");
            pill.classList.add(glowClass);
            if (icon) icon.textContent = iconChar;
            text.textContent = textStr;
            if (badge) {
                badge.textContent = badgeText;
                badge.style.background = badgeBg;
                badge.style.color = badgeColor;
            }
        }

        // --- CASE 1: PUBLIC HOLIDAY ---
        if (holiday) {
            const hName = isMs ? holiday.ms : holiday.en;
            applyPill(
                "glow-pku-closed",
                "\u{1F512}",
                isMs ? `Ditutup Hari Ini \u00B7 ${hName}` : `Closed Today \u00B7 ${hName}`,
                isMs ? "Cuti Am" : "Holiday",
                "rgba(239, 68, 68, 0.15)",
                "#ef4444"
            );
            return;
        }

        // --- CASE 2: WEEKENDS (Sat & Sun) ---
        if (day === 0 || day === 6) {
            const weekendBadge = isBreak ? (isMs ? "Cuti Sem" : "Semester Break") : (isMs ? "Hujung Minggu" : "Weekend");
            applyPill(
                "glow-pku-closed",
                "\u{1F512}",
                isMs ? "Ditutup Hari Ini \u00B7 Dibuka Isnin 8:00 PG" : "Closed Today \u00B7 Reopens Mon 8:00 AM",
                weekendBadge,
                "rgba(148, 163, 184, 0.15)",
                "#94a3b8"
            );
            return;
        }

        // Closing time for Main Campus: 5:00 PM during break, 7:00 PM during academic semester
        const closeMinutes = isBreak ? 1020 : 1140;
        const closeStrEn = isBreak ? "5:00 PM" : "7:00 PM";
        const closeStrMs = isBreak ? "5:00 PTG" : "7:00 PTG";
        const contextBadge = isBreak ? (isMs ? "Cuti Sem" : "Semester Break") : (isMs ? "Dibuka" : "Open");

        // --- CASE 3: BEFORE 8:00 AM ---
        if (timeMinutes < 480) {
            applyPill(
                "glow-pku-closed",
                "\u23F3",
                isMs ? "Ditutup \u00B7 Dibuka Hari Ini 8:00 PG" : "Closed \u00B7 Opens Today at 8:00 AM",
                isMs ? "Ditutup" : "Closed",
                "rgba(148, 163, 184, 0.15)",
                "#94a3b8"
            );
            return;
        }

        // --- CASE 4: FRIDAY REST / PRAYER BREAK (12:15 PM - 2:45 PM) ---
        if (day === 5 && timeMinutes >= 735 && timeMinutes < 885) {
            applyPill(
                "glow-pku-closed",
                "\u23F3",
                isMs ? "Rehat Solat Jumaat \u00B7 Dibuka 2:45 PTG" : "Friday Prayer Break \u00B7 Reopens 2:45 PM",
                isMs ? "Solat Jumaat" : "Prayer Break",
                "rgba(234, 179, 8, 0.15)",
                "#eab308"
            );
            return;
        }

        // --- CASE 5: MON - THU DAILY REST BREAK (1:00 PM - 2:00 PM) ---
        if (day >= 1 && day <= 4 && timeMinutes >= 780 && timeMinutes < 840) {
            applyPill(
                "glow-pku-closed",
                "\u23F3",
                isMs ? "Rehat Harian \u00B7 Dibuka 2:00 PTG" : "Daily Rest Break \u00B7 Reopens 2:00 PM",
                isMs ? "Waktu Rehat" : "Rest Break",
                "rgba(234, 179, 8, 0.15)",
                "#eab308"
            );
            return;
        }

        // --- CASE 6: OPERATING HOURS (OPEN) ---
        if (timeMinutes < closeMinutes) {
            if (day === 5 && timeMinutes < 735) {
                applyPill(
                    "glow-pku-open",
                    "\u{1FA7A}",
                    isMs ? "Dibuka Hari Ini \u00B7 8:00 PG \u2013 12:15 PTG" : "Open Today \u00B7 8:00 AM \u2013 12:15 PM",
                    contextBadge,
                    "rgba(16, 185, 129, 0.15)",
                    "#10b981"
                );
            } else if (day === 5 && timeMinutes >= 885) {
                applyPill(
                    "glow-pku-open",
                    "\u{1FA7A}",
                    isMs ? `Dibuka Hari Ini \u00B7 2:45 PTG \u2013 ${closeStrMs}` : `Open Today \u00B7 2:45 PM \u2013 ${closeStrEn}`,
                    contextBadge,
                    "rgba(16, 185, 129, 0.15)",
                    "#10b981"
                );
            } else {
                applyPill(
                    "glow-pku-open",
                    "\u{1FA7A}",
                    isMs ? `Dibuka Hari Ini \u00B7 8:00 PG \u2013 ${closeStrMs}` : `Open Today \u00B7 8:00 AM \u2013 ${closeStrEn}`,
                    contextBadge,
                    "rgba(16, 185, 129, 0.15)",
                    "#10b981"
                );
            }
            return;
        }

        // --- CASE 7: EVENING / NIGHT AFTER CLOSING ---
        if (day === 5) {
            applyPill(
                "glow-pku-closed",
                "\u{1F512}",
                isMs ? "Ditutup \u00B7 Dibuka Isnin 8:00 PG" : "Closed \u00B7 Reopens Mon 8:00 AM",
                isMs ? "Ditutup" : "Closed",
                "rgba(148, 163, 184, 0.15)",
                "#94a3b8"
            );
        } else {
            applyPill(
                "glow-pku-closed",
                "\u{1F512}",
                isMs ? "Ditutup Malam Ini \u00B7 Dibuka 8:00 PG" : "Closed Tonight \u00B7 Reopens 8:00 AM",
                isMs ? "Ditutup" : "Closed",
                "rgba(148, 163, 184, 0.15)",
                "#94a3b8"
            );
        }
    }

    // Interactive: Click pill to smooth scroll and focus PKU operating hours
    if (!pill.dataset.listenerAttached) {
        pill.dataset.listenerAttached = "true";
        pill.addEventListener("click", () => {
            const hoursHeader = document.getElementById("labelHealthHours");
            if (hoursHeader) {
                const card = hoursHeader.closest("div");
                if (card) {
                    card.scrollIntoView({ behavior: "smooth", block: "center" });
                    card.style.boxShadow = "0 0 0 3px rgba(16, 185, 129, 0.45)";
                    card.style.transition = "box-shadow 0.3s ease";
                    setTimeout(() => {
                        card.style.boxShadow = "";
                    }, 1500);
                }
            }
        });
    }

    updatePkuPill();
    setInterval(updatePkuPill, 60000);
}

if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", initPkuHoursPill);
} else {
    initPkuHoursPill();
}
